<?php $pageTitle='Events | StudentHub';require __DIR__.'/../includes/header.php'; ?><span class="eyebrow">Campus calendar</span><h1>Upcoming events</h1><p class="muted">Search the sample events list.</p><div class="toolbar"><label for="eventSearch">Search events</label><input id="eventSearch" type="search" placeholder="Search by title or category"></div><div class="grid" id="eventGrid"><?php $events=json_decode(file_get_contents(__DIR__.'/../data/events.json'),true);foreach($events as $event): ?><article class="card" data-search-item><div class="event-image" aria-hidden="true">✦</div><span class="pill"><?= e($event['category']) ?></span><h3><?= e($event['title']) ?></h3><p><?= e($event['description']) ?></p><small class="muted"><?= e($event['date']) ?></small></article><?php endforeach; ?></div><?php require __DIR__.'/../includes/footer.php'; ?>
